import inspect
from typing import ForwardRef

def evaluate_forwardref(annotation, globalns, localns):
    # Simplified version of evaluate_forwardref
    if isinstance(annotation, ForwardRef):
        return eval(annotation.__forward_arg__, globalns, localns)
    return annotation

class C:
    def __init__(self, a: "SomeType"):
        pass

# Mock SomeType in globals
globalns = {"SomeType": int}

# If call is C
call = C
# Current logic:
unwrapped = inspect.unwrap(call) # C
globalns_found = getattr(unwrapped, "__globals__", {}) # {}

# Proposed logic:
# get_globals(C) -> get_globals(C.__call__) -> type.__call__.__globals__
```

Wait, if `call` is a class, we should probably use `inspect.getmodule(call).__dict__`.

But let's see if we can just use `getattr(obj, "__globals__", None)` and if that fails, try to find it.

Actually, if `obj` is a class, `obj.__module__` tells us the module name.

But let's look at how `inspect.signature` does it. It doesn't provide globals.

If we want to be robust:

```python
def get_globals(obj):
    if hasattr(obj, "__globals__"):
        return obj.__globals__
    if hasattr(obj, "func"): # partial
        return get_globals(obj.func)
    if hasattr(obj, "__call__"):
        # Avoid infinite recursion if __call__ is the same object
        # or if it's a class (where __call__ is type.__call__)
        if isinstance(obj, type):
            # It's a class. Try to get its module's globals.
            module = inspect.getmodule(obj)
            if module:
                return module.__dict__
        return get_globals(obj.__call__)
    return {}
```

Wait, `get_globals(obj.__call__)` could lead to infinite recursion if `obj.__call__` is `obj`.

Let's refine `get_globals`.

```python
def get_globals(obj):
    # 1. Direct __globals__ (functions, methods)
    if hasattr(obj, "__globals__"):
        return obj.__globals__

    # 2. partials
    if hasattr(obj, "func"):
        return get_globals(obj.func)

    # 3. Callable classes (instances)
    if hasattr(obj, "__call__") and not isinstance(obj, type):
        return get_globals(obj.__call__)

    # 4. Classes
    if isinstance(obj, type):
        module = inspect.getmodule(obj)
        if module:
            return module.__dict__

    return {}
```

